 static void language(Context c,String value){language="en".equals(value)?"en":"az";android.content.SharedPreferences prefs=c.getSharedPreferences("interface",0);if(!language.equals(prefs.getString("language",null)))prefs.edit().putString("language",language).apply();}
 static String t(String value){if(!"en".equals(language))return value;String result=en.get(value);return result==null?value:result;}
 static void label(View v,String value){v.setTag(R.id.ui_label,value);v.setContentDescription(t(value));}
 static void text(TextView v,String value){v.setTag(R.id.ui_text,en.containsKey(value)?value:null);v.setText(t(value));}
 static void apply(View v){Object label=v.getTag(R.id.ui_label),text=v.getTag(R.id.ui_text);if(label instanceof String)v.setContentDescription(t((String)label));if(text instanceof String&&v instanceof TextView)((TextView)v).setText(t((String)text));if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)apply(g.getChildAt(i));}}
